  "outcome": "answered",
  "answer_parts": [
    {
      "text": "Who signs it: The assessment must be recorded in writing and “signed and dated by the competent person who completed it.”",
      "evidence_ids": [
        "ev-01",
        "ev-03"
      ]
    },
    {
      "text": "Who to share it with: Communicate the assessment’s findings and any control measures to every member of staff involved in the activity (not just file it centrally). The current version must also be readily accessible to staff at the point of the activity.",
      "evidence_ids": [
        "ev-01",
        "ev-02",
        "ev-02"
      ]
    },
    {
      "text": "How often it must be reviewed: Review the assessment at least annually, and sooner following an incident, a near miss, or any change to the activity, the people involved, or the environment. (The Health and Safety Policy Statement cross‑references the same annual-or-sooner requirement.)",
      "evidence_ids": [
        "ev-01",
        "ev-04"
      ]
    }
  ],
  "unsupported_aspects": []
}
